/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: artist, label, album, track, candidate, reuse, saved
 *   Constants: fresh, names
 * Tests
 *   - the approved order is Disc Number with unknown as 1, then Track Number with unknown last, then draft order
 *   - shown decisions are the unsaved Review edits whatever the revision, else the saved ones, and none once the edits are stale
 *   - buffered decisions are stale when a decided entry is gone or renamed or the decided label changed, never for Album or track decisions
 *   - a renamed or removed entry or label in the shown draft drops its decision, while reordering, roles, phrases, Album and track decisions keep theirs
 *   - the checklist names each identity as new, reused (marking a hidden record), needing a decision or changed, and counts what blocks approval
 *   - an append applies no entry or label, orders only the tracks it adds, and lists existing members after them in draft order
 *   - the confirmation marks Artist entries and the label resting only on file tags and automatic entries named like a label, unless appended, changed or decided
 *   - the publish body carries the shown changes and decisions with the saved cover, revision and approval digest
 *   - an append whose Album or member Track is no longer listed at its reviewed revision is a changed match that blocks approval
 *   - preselected rows read New or Reuses and block nothing, while rows neither answered nor preselected block; preselections never clear the tags-only marks
 * @end-catalog */

import type { ImportDecision } from './adminApi';
import type { ImportCandidate } from './importIdentity';
import { approvalBody, approvalChecklist, approvalTrackOrder, shownDecisions, staleDecisionEdits, staleDecisions } from './importApproval';
import { artistEntry, detail, entryKey, labelEntry, slotId, slotTwo } from './adminFixtures.testSupport';

const fresh = { action: 'create-distinct', candidateId: null, candidateRevision: null } as const;
/** The saved entry names of `saved()`, which each Artist decision is bound to. */
const names = ['Lorem', 'Ipsum', 'Dolor'];
const artist = (n: number, change: Partial<ImportDecision> = {}): ImportDecision => ({ scope: 'artist', slotId: null, entryKey: entryKey(n), boundName: names[n - 1] ?? null, ...fresh, ...change });
const label = (change: Partial<ImportDecision> = {}): ImportDecision => ({ scope: 'label', slotId: null, entryKey: null, boundName: 'Sit Records', ...fresh, ...change });
const album = (change: Partial<ImportDecision> = {}): ImportDecision => ({ scope: 'album', slotId: null, entryKey: null, boundName: null, ...fresh, ...change });
const track = (slot: string, change: Partial<ImportDecision> = {}): ImportDecision => ({ scope: 'track', slotId: slot, entryKey: null, boundName: null, ...fresh, ...change });
const candidate = (kind: ImportCandidate['kind'], id: string, name: string, visibility: 'public' | 'hidden' = 'public'): ImportCandidate =>
  ({ kind, id, label: name, revision: `r-${id}`, albumId: null, visibility, match: 'name', matchedSlotIds: [], automaticReuse: false });
const reuse = (value: ImportCandidate) => ({ action: 'reuse' as const, candidateId: value.id, candidateRevision: value.revision });
/** A saved project of two primaries, a featured entry and a label, with both tracks titled. */
function saved() {
  const item = detail();
  item.draft.album = { ...item.draft.album, title: 'Synthetic Album', artists: [{ ...artistEntry('Lorem'), joinPhrase: ' & ' }, artistEntry('Ipsum', entryKey(2)), artistEntry('Dolor', entryKey(3), 'featured')], label: labelEntry('Sit Records') };
  item.draft.tracks = [{ slotId, title: 'First', discNumber: null, trackNumber: null }, { slotId: slotTwo, title: 'Second', discNumber: null, trackNumber: null }];
  return item;
}

test('the approved order is Disc Number with unknown as 1, then Track Number with unknown last, then draft order', () => {
  const tracks = [{ id: 'a', discNumber: 2, trackNumber: 1 }, { id: 'b', discNumber: null, trackNumber: null }, { id: 'c', discNumber: 1, trackNumber: 2 },
    { id: 'd', discNumber: null, trackNumber: 1 }, { id: 'e', discNumber: 1, trackNumber: null }, { id: 'f', discNumber: 2, trackNumber: null }];
  expect(approvalTrackOrder(tracks).map(value => value.id)).toEqual(['d', 'c', 'b', 'e', 'a', 'f']);
  expect(approvalTrackOrder([])).toEqual([]);
});

test('shown decisions are the unsaved Review edits whatever the revision, else the saved ones, and none once the edits are stale', () => {
  const item = saved(); item.decisions = [artist(1), album()];
  const edits = { revision: item.revision, decisions: [artist(1), artist(2), label(), album(), track(slotId)] };
  expect(shownDecisions(item, item.draft, null)).toEqual(item.decisions);
  expect(shownDecisions(item, item.draft, edits)).toEqual(edits.decisions);
  const later = (kind: 'edit' | 'upload' | 'decisions' | 'publish') => ({ ...item, revision: item.revision + 5, valueRevision: 3, receipts: [{ operationId: '20000000-0000-4000-8000-000000000009', kind, revision: item.revision + 2 }] });
  // Field saves, uploads and automatic values since the first edit leave the edits shown.
  expect(shownDecisions(later('edit'), item.draft, edits)).toEqual(edits.decisions);
  expect(shownDecisions(later('upload'), item.draft, edits)).toEqual(edits.decisions);
  // Edits made for a renamed value, or older than decisions saved by another save or approval, are not shown.
  expect(shownDecisions(item, item.draft, { revision: item.revision, decisions: [artist(1, { boundName: 'Lorem Before' }), album()] })).toBeNull();
  expect(shownDecisions(item, item.draft, { revision: item.revision, decisions: [label({ boundName: 'Sit Records Before' })] })).toBeNull();
  expect(shownDecisions(later('decisions'), item.draft, edits)).toBeNull();
  expect(shownDecisions(later('publish'), item.draft, edits)).toBeNull();
  // A decisions receipt at or below the edits' revision was already seen.
  expect(staleDecisionEdits(later('decisions'), { ...edits, revision: item.revision + 2 })).toBe(false);
});

test('buffered decisions are stale when a decided entry is gone or renamed or the decided label changed, never for Album or track decisions', () => {
  const item = saved();
  expect(staleDecisions(item, [artist(1), artist(2), artist(3), label(), album(), track(slotId)])).toBe(false);
  for (const decisions of [[artist(1, { boundName: 'Renamed' })], [artist(9)], [label({ boundName: 'Sit Records Ltd' })], [artist(2, { boundName: null })]]) expect(staleDecisions(item, decisions)).toBe(true);
  expect(staleDecisions({ ...item, draft: { ...item.draft, album: { ...item.draft.album, label: null } } }, [label()])).toBe(true);
  expect(staleDecisions({ ...item, draft: { ...item.draft, album: { ...item.draft.album, title: 'Retitled' } } }, [album(), track(slotTwo)])).toBe(false);
});

test('a renamed or removed entry or label in the shown draft drops its decision, while reordering, roles, phrases, Album and track decisions keep theirs', () => {
  const item = saved(); item.decisions = [artist(1), artist(2), artist(3), label(), album(), track(slotId), track(slotTwo)];
  const [lorem, ipsum, dolor] = item.draft.album.artists;
  const reordered = { ...item.draft, album: { ...item.draft.album, artists: [{ ...ipsum, joinPhrase: ' x ' }, { ...lorem, role: 'featured' as const }, dolor] } };
  expect(shownDecisions(item, reordered, null)).toEqual(item.decisions);
  const renamed = { ...item.draft, album: { ...item.draft.album, artists: [{ ...lorem, name: 'Lorem Renamed' }, dolor], label: labelEntry('Sit Records Ltd') } };
  expect(shownDecisions(item, renamed, null)).toEqual([artist(3), album(), track(slotId), track(slotTwo)]);
  expect(shownDecisions(item, { ...item.draft, album: { ...item.draft.album, label: null } }, null)?.map(value => value.scope)).toEqual(['artist', 'artist', 'artist', 'album', 'track', 'track']);
  // A decision on a slot the project does not have is never shown.
  expect(shownDecisions(item, item.draft, { revision: item.revision, decisions: [track('10000000-0000-4000-8000-000000000009'), album()] })).toEqual([album()]);
});

test('the checklist names each identity as new, reused (marking a hidden record), needing a decision or changed, and counts what blocks approval', () => {
  const item = saved(), ipsum = candidate('artist', '1'.repeat(24), 'Ipsum', 'hidden'), sit = candidate('organization', '2'.repeat(24), 'Sit Records');
  const decisions = [artist(1), artist(2, reuse(ipsum)), label(reuse(sit)), album(), track(slotId, { action: 'skip' }), track(slotTwo)];
  const checklist = approvalChecklist(item.draft, decisions, [ipsum, sit]);
  expect(checklist.append).toBe(false);
  expect(checklist.artists.map(entry => [entry.name, entry.role, entry.joinPhrase, entry.identity])).toEqual([
    ['Lorem', 'primary', ' & ', { kind: 'new' }], ['Ipsum', 'primary', null, { kind: 'reused', label: 'Ipsum', hidden: true }], ['Dolor', 'featured', null, { kind: 'needsDecision' }]]);
  expect(checklist.label).toEqual({ name: 'Sit Records', identity: { kind: 'reused', label: 'Sit Records', hidden: false } });
  expect(checklist.album).toEqual({ kind: 'new' });
  // A skipped track is no catalog content.
  expect(checklist.tracks.map(value => [value.slotId, value.existing, value.identity])).toEqual([[slotTwo, false, { kind: 'new' }]]);
  expect(checklist.blocked).toBe(1);
  // A reused record no longer listed at its reviewed revision is a changed match; a skipped Artist or a missing Album decision needs one.
  const changed = approvalChecklist(item.draft, [artist(1, { action: 'skip' }), artist(2, reuse(ipsum)), artist(3), label(reuse(sit))], [{ ...ipsum, revision: 'r-newer' }]);
  expect([changed.artists.map(entry => entry.identity.kind), changed.label?.identity.kind, changed.album.kind, changed.tracks.map(value => value.identity.kind), changed.blocked])
    .toEqual([['needsDecision', 'changed', 'new'], 'changed', 'needsDecision', ['needsDecision', 'needsDecision'], 6]);
  expect(approvalChecklist({ ...item.draft, album: { ...item.draft.album, label: null } }, [], []).label).toBeNull();
});

test('an append applies no entry or label, orders only the tracks it adds, and lists existing members after them in draft order', () => {
  const item = saved(), target = candidate('album', '3'.repeat(24), 'Existing Album'), member = candidate('track', '4'.repeat(24), 'Second');
  const third = '10000000-0000-4000-8000-000000000003', fourth = '10000000-0000-4000-8000-000000000004', other = candidate('track', '5'.repeat(24), 'Stored Title');
  // The members' draft positions (Disc 1 before the new tracks) are not what the append keeps: it keeps each member's stored position.
  item.draft.tracks = [{ slotId, title: 'First', discNumber: 2, trackNumber: 1 }, { slotId: slotTwo, title: 'Second', discNumber: 1, trackNumber: 5 },
    { slotId: third, title: 'Third', discNumber: 1, trackNumber: 2 }, { slotId: fourth, title: 'Draft Title', discNumber: 1, trackNumber: 1 }];
  const checklist = approvalChecklist(item.draft, [album(reuse(target)), track(slotId), track(slotTwo, reuse(member)), track(third), track(fourth, reuse(other))], [target, member, other]);
  expect([checklist.append, checklist.artists.map(entry => entry.identity.kind), checklist.label?.identity.kind, checklist.album, checklist.blocked])
    .toEqual([true, ['notApplied', 'notApplied', 'notApplied'], 'notApplied', { kind: 'reused', label: 'Existing Album', hidden: false }, 0]);
  expect(checklist.tracks.map(value => [value.slotId, value.existing, value.identity])).toEqual([[third, false, { kind: 'new' }], [slotId, false, { kind: 'new' }],
    [slotTwo, true, { kind: 'reused', label: 'Second', hidden: false }], [fourth, true, { kind: 'reused', label: 'Stored Title', hidden: false }]]);
});

test('the confirmation marks Artist entries and the label resting only on file tags and automatic entries named like a label, unless appended, changed or decided', () => {
  const item = saved(), decisions = [artist(1, { action: 'skip' }), label({ action: 'skip' }), album()];
  const marks = { automaticPaths: ['album.artists', 'album.label', 'album.title'], possibleLabelEntryKeys: [entryKey(2)], changedPaths: [] as string[] };
  const marked = approvalChecklist(item.draft, decisions, [], marks);
  expect([marked.artistsFromTags, marked.labelFromTags, marked.artists.map(entry => entry.possibleLabel)]).toEqual([true, true, [false, true, false]]);
  // An explicit identity decision shown with the approval, saved or unsaved, makes that value the administrator's own: any one
  // entry's decision unmarks every entry, and the label's unmarks the label.
  const entryDecided = approvalChecklist(item.draft, [artist(3), album()], [], marks), labelDecided = approvalChecklist(item.draft, [label(reuse(candidate('organization', '2'.repeat(24), 'Sit Records'))), album()], [], marks);
  expect([entryDecided.artistsFromTags, entryDecided.labelFromTags, entryDecided.artists.some(entry => entry.possibleLabel)]).toEqual([false, true, false]);
  expect([labelDecided.artistsFromTags, labelDecided.labelFromTags]).toEqual([true, false]);
  // Without markers, with the value changed in this approval, or in an append, nothing is marked.
  for (const checklist of [approvalChecklist(item.draft, decisions, []), approvalChecklist(item.draft, decisions, [], { ...marks, changedPaths: ['album.artists', 'album.label'] }),
    approvalChecklist(item.draft, [album(reuse(candidate('album', '3'.repeat(24), 'Existing Album')))], [candidate('album', '3'.repeat(24), 'Existing Album')], marks)])
    expect([checklist.artistsFromTags, checklist.labelFromTags, checklist.artists.some(entry => entry.possibleLabel)]).toEqual([false, false, false]);
  // Empty entries or no label rest on nothing.
  const empty = approvalChecklist({ ...item.draft, album: { ...item.draft.album, artists: [], label: null } }, [album()], [], marks);
  expect([empty.artistsFromTags, empty.labelFromTags]).toEqual([false, false]);
});

test('the publish body carries the shown changes and decisions with the saved cover, revision and approval digest', () => {
  const item = saved(); item.revision = 7; item.selectedCoverSlotId = 'cover';
  const changes = [{ path: 'album.title', base: 'Synthetic Album', value: 'Retitled' }], decisions = [artist(1), album()];
  expect(approvalBody(item, changes, decisions)).toEqual({ expectedRevision: 7, changes, decisions, selectedCoverSlotId: 'cover', approvalDigest: 'e'.repeat(64) });
});

test('an append whose Album or member Track is no longer listed at its reviewed revision is a changed match that blocks approval', () => {
  const item = saved(), target = candidate('album', '3'.repeat(24), 'Existing Album'), member = candidate('track', '4'.repeat(24), 'Second');
  const decisions = [album(reuse(target)), track(slotId), track(slotTwo, reuse(member))];
  const gone = approvalChecklist(item.draft, decisions, [{ ...target, revision: 'r-newer' }]);
  // Still an append: its entries and label stay not applied, while the changed Album and member each block.
  expect([gone.append, gone.album, gone.tracks.map(value => [value.existing, value.identity.kind]), gone.artists.every(entry => entry.identity.kind === 'notApplied'), gone.blocked])
    .toEqual([true, { kind: 'changed' }, [[false, 'new'], [true, 'changed']], true, 2]);
});

test('preselected rows read New or Reuses and block nothing, while rows neither answered nor preselected block; preselections never clear the tags-only marks', () => {
  const item = saved(), member = { ...candidate('track', '4'.repeat(24), 'Stored Title'), match: 'sha256' as const };
  const marks = { automaticPaths: ['album.artists', 'album.label'], possibleLabelEntryKeys: [] as string[], changedPaths: [] as string[] };
  // Lorem has a candidate and no answer; every other row is preselected.
  const preselections = [artist(2), artist(3), label(), album(), track(slotId), track(slotTwo)];
  const checklist = approvalChecklist(item.draft, [], [candidate('artist', '1'.repeat(24), 'Lorem')], marks, preselections);
  expect([checklist.artists.map(entry => entry.identity.kind), checklist.label?.identity.kind, checklist.album.kind, checklist.tracks.map(value => value.identity.kind), checklist.blocked])
    .toEqual([['needsDecision', 'new', 'new'], 'new', 'new', ['new', 'new'], 1]);
  // Values resting on file tags stay marked: a preselection is not the administrator's own decision.
  expect([checklist.artistsFromTags, checklist.labelFromTags]).toEqual([true, true]);
  // An explicit answer wins over a preselection, and a preselected reuse of an append member is listed as an existing member.
  const target = candidate('album', '3'.repeat(24), 'Existing Album');
  const append = approvalChecklist(item.draft, [album(reuse(target)), track(slotTwo, { action: 'skip' })], [target, member], marks, [track(slotId, reuse(member)), track(slotTwo)]);
  expect([append.append, append.tracks.map(value => [value.slotId, value.existing, value.identity]), append.blocked]).toEqual([true, [[slotId, true, { kind: 'reused', label: 'Stored Title', hidden: false }]], 0]);
});
